import { useState } from "react";
import { motion } from "framer-motion";
import { offices, demographics } from "../../content";
import SectionHeading from "./SectionHeading";
import { EASE } from "./tokens";
import { useDynamicContent } from "../../hooks/useDynamicContent";

/**
 * Accurate-enough Afghanistan outline (including the Wakhan corridor),
 * generated by projecting real border coordinates into this 1000x620
 * viewBox. City markers below use the same projection, so each sits at
 * its true geographic position within the country.
 */
const AFG_PATH =
  "M61.1,197.0 L129.5,221.5 L181.2,183.4 L281.9,153.7 L365.8,67.2 L417.4,87.2 L500.0,98.8 L543.0,34.9 L597.3,100.1 L658.4,71.7 L669.1,62.0 L721.5,120.8 L751.7,127.9 L797.3,113.0 L869.8,77.5 L985.2,82.7 L953.0,108.5 L852.3,119.5 L785.2,142.1 L747.7,158.9 L754.4,197.0 L735.6,239.0 L710.1,302.2 L726.2,310.6 L672.5,344.9 L646.3,400.4 L605.4,439.2 L579.2,457.2 L554.4,451.4 L502.7,459.8 L495.3,477.9 L445.6,477.9 L408.1,514.1 L406.0,569.0 L318.8,596.1 L271.8,590.3 L218.1,596.1 L151.0,605.8 L38.3,572.9 L99.3,514.1 L94.0,472.8 L43.0,461.8 L37.6,415.9 L15.4,324.2 L44.3,284.2 L15.4,262.9 Z";

const CITIES: Record<string, { x: number; y: number; note: string }> = {
  Kabul: { x: 595.3, y: 269.3, note: "Head office" },
  Jalalabad: { x: 681.2, y: 276.4, note: "Eastern region" },
  Mazar: { x: 457.0, y: 128.5, note: "Northern region" },
  Herat: { x: 127.5, y: 280.9, note: "Western region" },
  Kandahar: { x: 363.1, y: 457.9, note: "Southern region" },
};

export default function WhereWeWork2() {
  const [active, setActive] = useState<string | null>(null);

  const eyebrow = useDynamicContent("home2.wherewework.eyebrow", "Our Footprint");
  const heading = useDynamicContent("home2.wherewework.heading", "Where We Work");
  const intro = useDynamicContent(
    "home2.wherewework.intro",
    "ACE delivers on the ground across five provinces, with a head office in Kabul and regional offices covering the north, south, east and west."
  );

  return (
    <section className="py-16 sm:py-20 lg:py-24 bg-white overflow-hidden">
      <div className="mx-auto max-w-[1240px] px-5 sm:px-8 lg:px-12">
        <SectionHeading
          eyebrow={eyebrow}
          title={heading}
          right={
            <p className="leading-relaxed text-[#073B70]/75" style={{ fontWeight: 700, fontSize: "17px" }}>
              {intro}
            </p>
          }
        />

        <div className="grid grid-cols-1 lg:grid-cols-[1.5fr_1fr] gap-10 lg:gap-14 items-center">
          <motion.div
            initial={{ opacity: 0, scale: 0.97 }}
            whileInView={{ opacity: 1, scale: 1 }}
            viewport={{ once: false, margin: "-80px" }}
            transition={{ duration: 0.9, ease: EASE }}
            className="relative overflow-hidden rounded-2xl bg-[#073B70] p-6 sm:p-10"
          >
            <svg viewBox="0 0 1000 620" className="w-full">
              {/* Country outline draws itself in */}
              <motion.path
                d={AFG_PATH}
                fill="#F5C518"
                fillOpacity={0.12}
                stroke="#F5C518"
                strokeOpacity={0.7}
                strokeWidth={3}
                strokeLinejoin="round"
                initial={{ pathLength: 0, fillOpacity: 0 }}
                whileInView={{ pathLength: 1, fillOpacity: 0.12 }}
                viewport={{ once: false }}
                transition={{ duration: 2, ease: EASE }}
              />

              {offices.map((city, i) => {
                const c = CITIES[city];
                if (!c) return null;
                const isActive = active === city;
                return (
                  <g
                    key={city}
                    onMouseEnter={() => setActive(city)}
                    onMouseLeave={() => setActive(null)}
                    style={{ cursor: "pointer" }}
                  >
                    {/* Pulsing halo */}
                    <motion.circle
                      cx={c.x}
                      cy={c.y}
                      r={22}
                      fill="#F5C518"
                      initial={{ opacity: 0 }}
                      whileInView={{ scale: [1, 1.8, 1], opacity: [0.35, 0, 0.35] }}
                      viewport={{ once: false }}
                      transition={{
                        duration: 2.4,
                        repeat: Infinity,
                        ease: "easeInOut",
                        delay: 1.4 + i * 0.2,
                      }}
                      style={{ transformOrigin: `${c.x}px ${c.y}px` }}
                    />
                    <motion.circle
                      cx={c.x}
                      cy={c.y}
                      r={isActive ? 15 : 11}
                      fill="#F5C518"
                      stroke="#073B70"
                      strokeWidth={4}
                      initial={{ scale: 0 }}
                      whileInView={{ scale: 1 }}
                      viewport={{ once: false }}
                      transition={{ duration: 0.5, delay: 1.4 + i * 0.15, ease: EASE }}
                      style={{ transformOrigin: `${c.x}px ${c.y}px` }}
                    />
                    <motion.text
                      x={c.x + 24}
                      y={c.y + 8}
                      fill="#ffffff"
                      fontSize={26}
                      fontWeight={600}
                      style={{ fontFamily: "Urbanist, sans-serif" }}
                      initial={{ opacity: 0 }}
                      whileInView={{ opacity: isActive ? 1 : 0.75 }}
                      viewport={{ once: false }}
                      transition={{ duration: 0.5, delay: 1.6 + i * 0.15 }}
                    >
                      {city}
                    </motion.text>
                  </g>
                );
              })}
            </svg>
          </motion.div>

          <motion.div
            initial="hidden"
            whileInView="visible"
            viewport={{ once: false, margin: "-80px" }}
            variants={{ hidden: {}, visible: { transition: { staggerChildren: 0.09 } } }}
          >
            <ul className="divide-y divide-[#073B70]/10 rounded-2xl border border-[#073B70]/10 overflow-hidden">
              {offices.map((city) => (
                <motion.li
                  key={city}
                  variants={{
                    hidden: { opacity: 0, x: 24 },
                    visible: { opacity: 1, x: 0, transition: { duration: 0.6, ease: EASE } },
                  }}
                  onMouseEnter={() => setActive(city)}
                  onMouseLeave={() => setActive(null)}
                  className={`flex items-center justify-between gap-4 px-5 py-4 transition-colors duration-300 ${
                    active === city ? "bg-[#F5C518]/15" : "bg-white"
                  }`}
                >
                  <span
                    className="text-[#073B70]"
                    style={{ fontFamily: "Urbanist, sans-serif", fontWeight: 800, fontSize: "19px" }}
                  >
                    {city}
                  </span>
                  <span className="text-[14.5px] font-semibold text-[#073B70]/65">{CITIES[city]?.note}</span>
                </motion.li>
              ))}
            </ul>

            <motion.div
              variants={{
                hidden: { opacity: 0, y: 20 },
                visible: { opacity: 1, y: 0, transition: { duration: 0.6, ease: EASE } },
              }}
              className="mt-7"
            >
              <p
                className="mb-3 text-[#073B70]"
                style={{ fontFamily: "Urbanist, sans-serif", fontWeight: 700, fontSize: "17px" }}
              >
                Who we serve
              </p>
              <div className="flex flex-wrap gap-2">
                {demographics.map((d) => (
                  <span
                    key={d}
                    className="rounded-full border border-[#073B70]/15 px-4 py-2 text-[14.5px] font-semibold text-[#073B70]/80"
                  >
                    {d}
                  </span>
                ))}
              </div>
            </motion.div>
          </motion.div>
        </div>
      </div>
    </section>
  );
}
